insert into chapters (book_id, chapter_no, title_ml, title_ar, start_page) select id, 164, 'പുനരുത്ഥാനം', null, 896 from books where volume_id=1 and book_no=31 on conflict (book_id, chapter_no) do nothing;
insert into chapters (book_id, chapter_no, title_ml, title_ar, start_page) select id, 165, 'ആദ്യമായി വസ്ത്രം ധരിപ്പിക്കപ്പെടുന്നവൻ', null, 897 from books where volume_id=1 and book_no=31 on conflict (book_id, chapter_no) do nothing;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 1, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَامَ أَعْرَابِيٌّ فَبَالَ فِي الْمَسْجِدِ، فَتَنَاوَلَهُ النَّاسُ، فَقَالَ لَهُمُ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "دَعُوهُ وَهَرِيقُوا عَلَى بَوْلِهِ سَجْلًا مِنْ مَاءٍ،– وَفِي رِوَايَةٍ: أَوْدلوًا – أَوْ ذُنُوبًا مِنْ مَاءٍ، فَإِنَّمَا بُعِثْتُمْ مُيَسِّرِينَ، وَلَمْ تُبْعَثُوا مُعَسِّرِينَ". (ق,د,ت,ن)', 'അബൂഹുറൈറ(റ): ഒരു ഗ്രാമവാസി പള്ളിയിൽ നിന്ന് മൂത്രമൊഴിച്ചു. അപ്പോൾ ആളുകൾ അദ്ദേഹത്തെ കൈകാര്യം ചെയ്യാനൊരുങ്ങി. നബി(സ) അവരോടു പറഞ്ഞു: "നിങ്ങൾ അവനെ വിട്ടേക്കുക (അയാൾ മൂത്രമൊഴിക്കട്ടെ). ഒരു തോൽപാത്രം വെള്ളം (ഒരു റിപ്പോർട്ടിൽ: ഒരു ബക്കറ്റ് വെള്ളം.) അല്ലെങ്കിൽ ഒരു വലിയ ബക്കറ്റ് വെള്ളം കൊണ്ടുവന്ന് മൂത്രമൊഴിച്ച സ്ഥലത്ത് ഒഴിക്കുക. നിങ്ങളെ നിയോഗിച്ചിരിക്കുന്നത് (ജനങ്ങൾക്ക്) ആശ്വാസം നൽകുവാനാണ്. പ്രയാസം സൃഷ്ടിക്കുവാനല്ല". (ബു,മു,ദ,തു,ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','د','ت','ن']::text[], array['ബു','മു','ദ','തു','ന']::text[], null, null, 143, 143, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=10 and h.hadith_no=1), 1, 'وَفِي رِوَايَةٍ: أَوْدلوًا – أَوْ ذُنُوبًا مِنْ مَاءٍ، فَإِنَّمَا بُعِثْتُمْ مُيَسِّرِينَ، وَلَمْ تُبْعَثُوا مُعَسِّرِينَ". (ق,د,ت,ن)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 2, 'عَنْ أُمِّ قَيْسٍ بِنْتِ مِحْصَنٍ رَضِيَ اللهُ عَنْهَا: أَنَّهَا أَتَتْ بِابْنٍ لَهَا صَغِيرٍ، لَمْ يَأْكُلِ الطَّعَامَ، إِلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَأَجْلَسَهُ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي حَجْرِهِ، فَبَالَ عَلَى ثَوْبِهِ، فَدَعَا بِمَاءٍ، فَنَضَحَهُ وَلَمْ يَغْسِلْهُ. (ق,د,ن,جه)', 'ഉമ്മുവൈസുബിൻതുമിഹ്സ്വൻ(റ): ആഹാരം കഴിക്കാത്ത തന്റെ ഒരു കുട്ടിയേയുമായി ഉമ്മുൽഖൈസ് നബി(സ)യുടെ അടുക്കൽ ചെന്നു. നബി(സ) ആ കുട്ടിയെ എടുത്തു തന്റെ മടിയിലിരുത്തി. അവിടുത്തെ വസ്ത്രത്തിൽ കുട്ടി മൂത്രമൊഴിച്ചു. നബി(സ) വെള്ളം ആവശ്യപ്പെട്ടു. അതിൽ നിന്ന് അല്പമെടുത്തു വസ്ത്രത്തിൽ കുടഞ്ഞു, കഴുകിയില്ല.¹ (ബു,മു,ദ,ന,ജ)', 'أُمِّ قَيْسٍ بِنْتِ مِحْصَنٍ', 'ഉമ്മുവൈസുബിൻതുമിഹ്സ്വൻ(റ)', '¹. പാലല്ലാത്ത മറ്റൊന്നും കഴിക്കാത്ത രണ്ടു വയസ്സിൽ താഴെ പ്രായമുള്ള ആൺകുട്ടിയുടെ മൂത്രമേ ഇങ്ങനെ ശുദ്ധിയാക്കാൻ പറ്റൂ എന്ന് കാണാം.', null, array['ق','د','ن','جه']::text[], array['ബു','മു','ദ','ന','ജ']::text[], null, null, 143, 143, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 3, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: دَخَلَ أَعْرَابِيٌّ الْمَسْجِدَ وَرَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ جَالِسٌ، فَقَالَ: اللَّهُمَّ اغْفِرْ لِي وَلِمُحَمَّدٍ، وَلَا تَغْفِرْ لِأَحَدٍ مَعَنَا. فَضَحِكَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَقَالَ: "لَقَدِ احْتَظَرْتَ وَاسِعًا". ثُمَّ وَلَّى، حَتَّى إِذَا كَانَ فِي نَاحِيَةِ الْمَسْجِدِ فَشَجَ يَبُولُ، فَقَالَ الْأَعْرَابِيُّ بَعْدَ أَنْ فَقِهَ فَقَامَ: إِلَيَّ، بِأَبِي أَنْتَ وَأُمِّي، فَلَمْ يُؤَنِّبْ وَلَمْ يَسُبَّ، فَقَالَ: "إِنَّ هَذَا الْمَسْجِدَ لَا يُبَالُ فِيهِ، وَإِنَّمَا بُنِيَ لِذِكْرِ اللهِ وَلِلصَّلَاةِ". ثُمَّ أَمَرَ بِسَجْلٍ مِنْ مَاءٍ فَأُفْرِغَ عَلَى بَوْلِهِ. (ت,جه)', 'അബൂഹുറൈറ(റ): നബി(സ) പള്ളിയിൽ ഇരിക്കവെ ഒരു ഗ്രാമീണൻ (അപരിഷ്കൃതൻ) പള്ളിയിൽ കടന്നുവന്ന് പറഞ്ഞു: അല്ലാഹുവെ, എനിക്കും മുഹമ്മദിനും നീ പാപങ്ങൾ പൊറുത്തുതന്നാലും, ഞങ്ങളോടൊപ്പം മറ്റാർക്കും നീ പൊറുത്തു കൊടുക്കരുത്. അപ്പോൾ നബി(സ) ചിരിച്ചുകൊണ്ടു പറഞ്ഞു: "(അല്ലാഹുവിന്റെ കാരുണ്യമായ) വിശാലതയെ നീ പരിമിതമാക്കി." ശേഷം അയാൾ തിരികെ നടന്നു. അങ്ങനെ പള്ളിയുടെ ഒരു മൂലയിലെത്തിയപ്പോൾ രണ്ടു കാലുകളും അകറ്റിവെച്ച് മൂത്രമൊഴിച്ചു. പിന്നീട് കാര്യങ്ങളെല്ലാം മനസ്സിലാക്കിയപ്പോൾ അയാൾ എഴുന്നേറ്റ് പറഞ്ഞു: എന്റെ മാതാപിതാക്കൾ അങ്ങേക്കു സമർപ്പിതം. നബി(സ) അയാളെ ആക്ഷേപിക്കുകയോ ശകാരിക്കുകയോ ചെയ്തില്ല. നബി(സ) പറഞ്ഞു: "നിശ്ചയം ഈ പള്ളിയിൽ മൂത്രമൊഴിക്കരുത്. (അതിനു വേണ്ടിയല്ല നിർമ്മിച്ചത്) അല്ലാഹുവിനെ ദിക്ർ ചെയ്യാനും നിസ്കാരത്തിനും വേണ്ടി മാത്രമാണ് അത് നിർമ്മിക്കപ്പെട്ടിരിക്കുന്നത്." പിന്നെ ഒരു ബക്കറ്റ് വെള്ളം കൊണ്ടുവരാൻ കൽപിക്കുകയും മൂത്രമൊഴിച്ച സ്ഥലത്ത് അത് ഒഴിക്കുകയും ചെയ്തു. (തു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 143, 144, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 4, 'عَنْ عَبْدِ اللهِ بْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ سُئِلَ عَنِ الْمَاءِ يَكُونُ بِالْفَلَاةِ مِنَ الْأَرْضِ، وَمَا يَنُوبُهُ مِنَ الدَّوَابِّ وَالسِّبَاعِ؟ فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِذَا بَلَغَ الْمَاءُ قُلَّتَيْنِ لَمْ يُنَجِّسْهُ شَيْءٌ". وَفِي رِوَايَةٍ: "إِذَا كَانَ الْمَاءُ قُلَّتَيْنِ – أَوْ: ثَلَاثًا – لَمْ يُنَجِّسْهُ شَيْءٌ". (د,ت,جه)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): മരുഭൂമിയിലെ വെള്ളത്തെക്കുറിച്ചും, ഇഴജന്തുക്കളും വന്യജീവികളും വന്നിറങ്ങുന്ന വെള്ളത്തെകുറിച്ചും നബി(സ)യോട് ചോദിക്കുന്നതു ഞാൻ കേട്ടു. അപ്പോൾ നബി(സ) മറുപടി പറഞ്ഞു: "വെള്ളം രണ്ടു ഖുല്ലത്തുണ്ടെങ്കിൽ² യാതൊന്നും അതിനെ മലിനമാക്കുകയില്ല." (ഒരു റിപ്പോർട്ടിൽ: വെള്ളം മലിനമാകുകയില്ല). (ദ,തു,ജ)', 'عَبْدِ اللهِ بْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', '². ഒന്നേകാൽ മുഴം നീളവും വീതിയും ആഴമുള്ള ഒരു പാത്രത്തിന്റെ വ്യാപ്തം, ഏകദേശം ഇരുനൂറ് ലിറ്റർ, അഥവാ 189 കിഗ്രാം.', null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 144, 144, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=10 and h.hadith_no=4), 1, 'وَفِي رِوَايَةٍ: "إِذَا كَانَ الْمَاءُ قُلَّتَيْنِ – أَوْ: ثَلَاثًا – لَمْ يُنَجِّسْهُ شَيْءٌ". (د,ت,جه)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 5, 'عَنْ مَيْمُونَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ سُئِلَ عَنْ فَأْرَةٍ سَقَطَتْ فِي سَمْنٍ، فَقَالَ: "أَلْقُوهَا وَمَا حَوْلَهَا فَاطْرَحُوهُ، وَكُلُوا سَمْنَكُمْ". (خ)', 'മൈമൂന(റ): എലി നെയ്യിൽ വീണാൽ എന്തു ചെയ്യണമെന്ന് നബി(സ)യോട് ചോദിക്കപ്പെട്ടു. അപ്പോൾ അവിടുന്ന് പറഞ്ഞു: "എലിയെയും അതു വീണതിന്റെ ചുറ്റുഭാഗത്തുള്ളതും നീക്കം ചെയ്ത് നെയ്യ് ഭക്ഷിച്ചു കൊള്ളുക." (ബു)', 'مَيْمُونَةَ', 'മൈമൂന(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 144, 144, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 6, 'عَنْ عَبْدِ اللهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يُصَلِّي عِنْدَ الْبَيْتِ وَأَبُو جَهْلٍ وَأَصْحَابٌ لَهُ جُلُوسٌ إِذْ قَالَ بَعْضُهُمْ لِبَعْضٍ: أَيُّكُمْ يَجِيءُ بِسَلَى جَزُورِ بَنِي فُلَانٍ، فَيَضَعُهُ عَلَى ظَهْرِ مُحَمَّدٍ إِذَا سَجَدَ؟ فَانْبَعَثَ أَشْقَى الْقَوْمِ فَجَاءَ بِهِ، فَنَظَرَ حَتَّى سَجَدَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، وَضَعَهُ عَلَى ظَهْرِهِ بَيْنَ كَتِفَيْهِ، وَأَنَا أَنْظُرُ لَا أُغَيِّرُ شَيْئًا، لَوْ كَانَ لِي مَنَعَةٌ، قَالَ: فَجَعَلُوا يَضْحَكُونَ وَيُحِيلُ بَعْضُهُمْ عَلَى بَعْضٍ، وَرَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ سَاجِدٌ لَا يَرْفَعُ رَأْسَهُ، حَتَّى جَاءَتْهُ فَاطِمَةُ، فَطَرَحَتْ عَنْ ظَهْرِهِ، فَرَفَعَ رَأْسَهُ ثُمَّ قَالَ: "اللَّهُمَّ عَلَيْكَ بِقُرَيْشٍ". ثَلَاثَ مَرَّاتٍ، فَشَقَّ عَلَيْهِمْ إِذْ دَعَا عَلَيْهِمْ، قَالَ: وَكَانُوا يَرَوْنَ أَنَّ الدَّعْوَةَ فِي ذَلِكَ الْبَلَدِ مُسْتَجَابَةٌ، ثُمَّ سَمَّى: "اللَّهُمَّ عَلَيْكَ بِأَبِي جَهْلٍ، وَعَلَيْكَ بِعُتْبَةَ بْنِ رَبِيعَةَ، وَشَيْبَةَ بْنِ رَبِيعَةَ، وَالْوَلِيدِ ابْنِ عُتْبَةَ، وَأُمَيَّةَ بْنِ خَلَفٍ، وَعُقْبَةَ بْنِ أَبِي مُعَيْطٍ" وَعَدَّ السَّابِعَ فَلَمْ يَحْفَظْهُ الرَّاوِي قَالَ: فَوَالَّذِي نَفْسِي بِيَدِهِ، لَقَدْ رَأَيْتُ الَّذِينَ عَدَّ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ صَرْعَى، فِي الْقَلِيبِ قَلِيبِ بَدْرٍ. (ق,ن)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): നബി(സ) കഅ്ബത്തിങ്കൽ വെച്ചു നിസ്കരിച്ചു, അബൂജഹലും കൂട്ടരും അവിടെ ഇരിക്കുന്നുണ്ടായിരുന്നു. അവർ പരസ്പരം പറഞ്ഞു: ഇന്നയാളുടെ ഒട്ടകത്തിന്റെ കുടൽമാല വലിച്ചു കൊണ്ടുവന്ന് മുഹമ്മദ് സുജൂദ് ചെയ്യുമ്പോൾ അദ്ദേഹത്തിന്റെ തലക്ക് മുകളിലേക്കിടാൻ ആരാണു തയ്യാറുള്ളത്?. കൂട്ടത്തിൽ ഏറ്റവും ദുഷ്ടനായ വ്യക്തി ചാടിയെഴുന്നേറ്റു. കുടൽ മാലയുമായെത്തി. നബി സുജൂദ് ചെയ്യുന്നതുവരെ അവൻ കാത്തിരുന്നു. സുജൂദ് ചെയ്തപ്പോൾ നബിയുടെ ചുമലിലേക്കവൻ അതെടുത്തിട്ടു. ഞാൻ നോക്കി നിൽക്കുകയായിരുന്നു. പക്ഷേ, എനിക്ക് ഒന്നും ചെയ്യാൻ കഴിയുമായിരുന്നില്ല. തടയാൻ എനിക്ക് കൂട്ടുകാരുണ്ടായിരുന്നെങ്കിൽ എന്ന് ഞാൻ ആഗ്രഹിച്ചു. ഇബ്നുമസ്ഊദ്(റ) പറയുന്നു: അവർ ചിരിച്ചു ചിരിച്ച് ചിലർ ചിലരുടെമേൽ വീഴാൻ തുടങ്ങി. നബി(സ)യാണെങ്കിൽ സുജൂദിൽ തന്നെയായിരുന്നു. തല ഉയർത്തുന്നില്ല. അങ്ങിനെ മകൾ ഫാതിമ(റ) വന്നു നബി(സ)യുടെ മുതുകിൽ നിന്ന് അതെടുത്തു മാറ്റിയപ്പോൾ നബി(സ) തല ഉയർത്തി. പിന്നെ: "അല്ലാഹുവേ, നീ ഖുറൈശികളെ പിടികൂടേണമേ" എന്ന് മൂന്ന് പ്രാവശ്യം പ്രാർത്ഥിച്ചു. ഈ പ്രാർത്ഥന അവരെ വല്ലാതെ വിഷമിപ്പിച്ചു. മക്കയിൽ നിന്നുള്ള പ്രാർത്ഥന സ്വീകരിക്കപ്പെടുമെന്ന് അവർ വിശ്വസിച്ചിരുന്നു. തുടർന്ന് അതിൽ ഓരോരുത്തരുടെയും പേരെടുത്തുകൊണ്ട് നബി(സ) പ്രാർത്ഥിച്ചു: "അല്ലാഹുവേ, നീ അബൂജഹലിനെ പിടികൂടേണമേ, റബീഅതിന്റെ പുത്രൻ ഉത്ബത്തിനെയും, റബീഅത്തിന്റെ പുത്രൻ ശൈബത്തിനെയും, ഉത്ബത്തിന്റെ പുത്രൻ വലീദിനെയും, ഖലഫിന്റെ പുത്രൻ ഉമയ്യത്തിനെയും, അബൂമുഐതിന്റെ പുത്രൻ ഉത്ബത്തിനെയും പിടികൂടേണമേ." (ഏഴാമത്തെ ആളെയും ഇബ്നുമസ്ഊദ്(റ) എണ്ണി. ഉദ്ധരിക്കുന്ന ആൾ അത് ആരാണെന്ന് മറന്നുപോയതാണ്.) ഇബ്നുമസ്ഊദ്(റ) പറയുന്നു: എന്റെ ആത്മാവ് ആരുടെ കൈയിലാണോ, അവനെതന്നെ സത്യം!, നബി(സ) അന്ന് എണ്ണിയ ആളുകളെല്ലാം വധിക്കപ്പെട്ടു. അവർ ബദ്റിലെ കിണറ്റിൽ കിടക്കുന്നത് ഞാൻ കാണുക തന്നെ ചെയ്തു. (ബു,മു,ന)', 'عَبْدِ اللهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['ق','ن']::text[], array['ബു','മു','ന']::text[], null, null, 144, 145, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 7, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "كُلُّ كَلْمٍ يُكْلَمُهُ الْمُسْلِمُ فِي سَبِيلِ اللهِ، يَكُونُ يَوْمَ الْقِيَامَةِ كَهَيْئَتِهَا، إِذْ طُعِنَتْ، تَفَجَّرُ دَمًا، اللَّوْنُ لَوْنُ الدَّمِ، وَالْعَرْفُ عَرْفُ الْمِسْكِ". (ق)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ മുസ്ലിമിന് ഏൽക്കുന്ന എല്ലാ മുറിവും അതേ രൂപത്തിൽ തന്നെയാണ് പുനരുദ്ധാരണ ദിവസം കാണപ്പെടുക. രക്തം ഒലിച്ചു കൊണ്ടേയിരിക്കും. നിറം രക്തത്തിന്റെ നിറം തന്നെ, പക്ഷേ മണം കസ്തൂരിയുടേതായിരിക്കും." (ബു,മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق']::text[], array['ബു','മു']::text[], null, null, 145, 145, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 8, 'عَنْ سَهْلِ بْنِ سَعْدٍ السَّاعِدِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّهُ سَأَلَهُ النَّاسُ: بِأَيِّ شَيْءٍ دُووِيَ جُرْحُ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ؟ فَقَالَ: مَا بَقِيَ أَحَدٌ أَعْلَمُ بِهِ مِنِّي، كَانَ عَلِيٌّ رَضِيَ اللهُ عَنْهُ يَجِيءُ بِتُرْسِهِ فِيهِ مَاءٌ، وَفَاطِمَةُ رَضِيَ اللهُ عَنْهَا تَغْسِلُ عَنْ وَجْهِهِ الدَّمَ، فَأُخِذَ حَصِيرٌ فَأُحْرِقَ، فَحُشِيَ بِهِ جُرْحُهُ. (ق)', 'സഹ്ൽ(റ): നബി(സ)ക്ക് (ഉഹ്ദിൽ) പറ്റിയ മുറിവിന്ന് എങ്ങനെയാണ് ചികിൽസിച്ചതെന്ന് ജനങ്ങൾ അദ്ദേഹത്തോട് ചോദിച്ചു. അതിനെക്കുറിച്ച് എന്നേക്കാളും അറിയുന്നവർ ഇന്ന് ജീവിച്ചിരിക്കുന്നില്ല എന്ന് പറഞ്ഞ ശേഷം അദ്ദേഹം പറഞ്ഞു: അലി(റ) തന്റെ പരിചയിൽ വെള്ളം കൊണ്ടുവന്നു. ഫാതിമ(റ) ആ വെള്ളം കൊണ്ട് നബി(സ)യുടെ മുഖം കഴുകി രക്തം നീക്കം ചെയ്തു. ഒരു പായ ചുട്ട് വെണ്ണീരാക്കിയ ശേഷം ആ വെണ്ണീർ മുറിവിൽ നിറച്ചു." (ബു,മു)', 'سَهْلِ بْنِ سَعْدٍ السَّاعِدِيِّ', 'സഹ്ൽ(റ)', null, null, array['ق']::text[], array['ബു','മു']::text[], null, null, 145, 145, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 9, 'عَنْ عَلِيٍّ رَضِيَ اللهُ عَنْهُ قَالَ: كُنْتُ رَجُلًا مَذَّاءً، فَجَعَلْتُ أَغْتَسِلُ حَتَّى تَشَقَّقَ ظَهْرِي، فَذَكَرْتُ ذَلِكَ لِلنَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، أَوْ ذُكِرَ لَهُ، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا تَفْعَلْ، إِذَا رَأَيْتَ الْمَذْيَ فَاغْسِلْ ذَكَرَكَ، وَتَوَضَّأْ وُضُوءَكَ لِلصَّلَاةِ، فَإِذَا فَضَخْتَ الْمَاءَ فَاغْتَسِلْ". (م,د,ن)', 'അലി(റ): ഞാൻ (വികാരമുള്ളപ്പോൾ) പെട്ടെന്ന് സുരതജലം (മദ്യ്)³ പുറപ്പെടുന്ന ആളായിരുന്നു. അതിനാൽ എന്റെ മുതുക് പൊളിയുമാറ് ഞാൻ കുളിക്കുമായിരുന്നു. ഈ വിവരം ഞാൻ നബി(സ)യോട് പറഞ്ഞപ്പോൾ - അല്ലെങ്കിൽ മറ്റാരെങ്കിലും പറഞ്ഞപ്പോൾ - നബി(സ) പറഞ്ഞു: "നീ അങ്ങനെ ചെയ്യേണ്ട. മദ്യ് കണ്ടാൽ നിന്റെ ലിംഗം കഴുകുകയും നിസ്കാരത്തിന് അവശ്യമായ വുദു ചെയ്യുകയും ചെയ്താൽ മതി. വെള്ളം തെറിച്ചു തെറിച്ചാണ് പുറപ്പെടുന്നതെങ്കിൽ (ശുക്ല പ്രവാഹമാണുണ്ടാകുന്നതെങ്കിൽ) നീ കുളിക്കുകയും ചെയ്യുക." (മു,ദ,ന)', 'عَلِيٍّ', 'അലി(റ)', '³. ശുക്ലസ്രാവത്തിനു അഥവാ വികാരം മൂർച്ചിക്കുന്നതിന്റെ തൊട്ടു മുമ്പ് പുറപ്പെടുന്ന ദ്രാവകമാണ് മദ്യ്.', null, array['م','د','ن']::text[], array['മു','ദ','ന']::text[], null, null, 145, 145, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 10, 'عَنِ الْمِقْدَادِ بْنِ الْأَسْوَدِ رَضِيَ اللهُ عَنْهُ: أَنَّ عَلِيًّا رَضِيَ اللهُ عَنْهُ أَمَرَهُ أَنْ يَسْأَلَ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: عَنِ الرَّجُلِ إِذَا دَنَا مِنْ أَهْلِهِ فَخَرَجَ مِنْهُ الْمَذْيُ، مَاذَا عَلَيْهِ؟ فَإِنَّ عِنْدِي ابْنَتَهُ، وَأَنَا أَسْتَحِي أَنْ أَسْأَلَهُ. قَالَ مِقْدَادٌ: فَسَأَلْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَنْ ذَلِكَ، فَقَالَ: "إِذَا وَجَدَ أَحَدُكُمْ ذَلِكَ فَلْيَنْضَحْ فَرْجَهُ – وَفِي رِوَايَةٍ: لِيَغْسِلْ ذَكَرَهُ وَأُنْثَيَيْهِ – وَلْيَتَوَضَّأْ وُضُوءَهُ لِلصَّلَاةِ". (ق,د,ن,جه)', 'മിഖ്ദാദുബ്നുഅസ്വദ്(റ): ഭാര്യയെ സമീപിക്കുമ്പോൾ മദ്യ് പുറപ്പെടുന്നയാൾക്ക് നിർബന്ധമായ കാര്യം എന്താണെന്ന് നബി(സ)യോട് തനിക്കുവേണ്ടി ചോദിക്കുവാൻ അലി(റ) മിഖ്ദാദി(റ)നോട് കൽപിച്ചു. തന്നോടൊപ്പം നബി(സ)യുടെ മകളുള്ളതിനാൽ ഈ വിഷയം നബി(സ)യോട് നേരിട്ട് ചോദിക്കുന്നതിൽ ഞാൻ ലജ്ജിതനാണ് എന്ന് അലി(റ) പറഞ്ഞു. മിഖ്ദാദ്(റ) പറയുന്നു: അതിനെക്കുറിച്ച് ഞാൻ നബിയോട് ചോദിച്ചു: അപ്പോൾ നബി(സ) പറഞ്ഞു: "നിങ്ങളിലൊരാൾ അങ്ങനെ കണ്ടാൽ അവൻ ഗുഹ്യഭാഗം കഴുകട്ടെ. (മറ്റൊരു റിപ്പോർട്ടിൽ: അവൻ തന്റെ ലിംഗവും രണ്ടു വൃഷ്ണങ്ങളും കഴുകട്ടെ) നിസ്കാരത്തിന്നുള്ള വുളുഉം ചെയ്തുകൊള്ളട്ടെ." (ബു,മു,ദ,ന,ജ)', 'الْمِقْدَادِ بْنِ الْأَسْوَدِ', 'മിഖ്ദാദുബ്നുഅസ്വദ്(റ)', null, null, array['ق','د','ن','جه']::text[], array['ബു','മു','ദ','ന','ജ']::text[], null, null, 145, 146, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=10 and h.hadith_no=10), 1, 'وَفِي رِوَايَةٍ: لِيَغْسِلْ ذَكَرَهُ وَأُنْثَيَيْهِ – وَلْيَتَوَضَّأْ وُضُوءَهُ لِلصَّلَاةِ". (ق,د,ن,جه)', 'മറ്റൊരു നിവേദനിൽ: അവൻ തന്റെ ലിംഗവും രണ്ടു വൃഷ്ണങ്ങളും കഴുകട്ടെ) നിസ്കാരത്തിന്നുള്ള വുളുഉം ചെയ്തുകൊള്ളട്ടെ." (ബു,മു,ദ,ന,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 11, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: بَزَقَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي ثَوْبِهِ. (خ)', 'അനസ്(റ): ഒരിക്കൽ നബി(സ) നിസ്കരിക്കുമ്പോൾ തന്റെ വസ്ത്രത്തിൽ (ടവലിൽ) തുപ്പി.⁴ (ബു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസ്(റ)', '⁴. പള്ളിയിൽ തുപ്പാൻ പാടില്ല. തുപ്പുനീർ നജസല്ല കഫമോ മറ്റോ ഉണ്ടെങ്കിൽ നിസ്കരിച്ചു കൊണ്ടിരിക്കെ തുപ്പുനീർ വിഴുങ്ങാതെ അവ തൂവാലയോ മറ്റോ ഉപയോഗിച്ച് പുറത്തെടുക്കാൻ പഠിപ്പിക്കാനായിരിക്കണം നബി(സ) ഇങ്ങനെ ചെയ്തത്.', null, array['خ']::text[], array['ബു']::text[], null, null, 146, 146, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 12, 'عَنْ هَمَّامِ بْنِ الْحَارِثِ قَالَ: ضَافَ عَائِشَةَ رَضِيَ اللهُ عَنْهَا – ضَيْفٌ، فَأَمَرْتُ لَهُ بِمِلْحَفَةٍ صَفْرَاءَ، فَنَامَ فِيهَا، فَاحْتَلَمَ، فَاسْتَحْيَا أَنْ يُرْسِلَ بِهَا وَبِهَا أَثَرُ الِاحْتِلَامِ، فَغَمَسَهَا فِي الْمَاءِ ثُمَّ أَرْسَلَ بِهَا، فَقَالَتْ عَائِشَةُ: لِمَ أَفْسَدَ عَلَيْنَا ثَوْبَنَا؟ إِنَّمَا كَانَ يَكْفِيهِ أَنْ يَفْرُكَهُ بِأَصَابِعِهِ، وَرُبَّمَا فَرَكْتُهُ مِنْ ثَوْبِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِأَصَابِعِي. حَسَنٌ صَحِيحٌ. (م,د,ن,جه,ت)', 'ഹമ്മാമുബ്നു ഹാരിസ്(റ): ആഇശ(റ)യുടെ വീട്ടിൽ ഒരു അതിഥി താമസിച്ചു. ആഇശ(റ) അദ്ദേഹത്തിനു ഒരു മഞ്ഞപുതപ്പ് കൊടുക്കാൻ കൽപിച്ചു. അദ്ദേഹം അതിൽ ഉറങ്ങി. അതിൽ സ്ഖലനമുണ്ടായി. ഇന്ദ്രിയത്തിന്റെ പാടുള്ള ആ പുതപ്പ് അതേരൂപത്തിൽ തിരിച്ചുനൽകാൻ അദ്ദേഹം ലജ്ജിച്ചു. അദ്ദേഹം അത് വെള്ളത്തിൽ മുക്കിയശേഷം തിരിച്ചു കൊടുത്തയച്ചപ്പോൾ ആഇശ(റ) ചോദിച്ചു: ഞങ്ങളുടെ പുതപ്പ് (വെള്ളത്തിൽ മുക്കി ചീത്തയാക്കിയതെന്തിനാ?) അത് വിരൽ കൊണ്ട് ചുരണ്ടിക്കളഞ്ഞാൽ മതിയാകുമായിരുന്നില്ലേ." ചിലപ്പോഴെല്ലാം നബി(സ)യുടെ വസ്ത്രത്തിൽ നിന്ന് വിരലുകൾ കൊണ്ടു ഞാനത് ചുരണ്ടിക്കളയാറുണ്ടായിരുന്നു. ഹദീസ് ഹസനും സഹീഹുമാണെന്ന് തുർമുദി പറയുന്നു. (മു,തു,ന,ദ,ജ)', 'هَمَّامِ بْنِ الْحَارِثِ قَالَ', 'ഹമ്മാമുബ്നു ഹാരിസ്(റ)', null, null, array['م','د','ن','جه','ت']::text[], array['മു','തു','ന','ദ','ജ']::text[], null, null, 146, 146, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 13, 'عَنْ سَهْلِ بْنِ حُنَيْفٍ رَضِيَ اللهُ عَنْهُ قَالَ: كُنْتُ أَلْقَى مِنَ الْمَذْيِ شِدَّةً، وَكُنْتُ أُكْثِرُ مِنَ الِاغْتِسَالِ، فَسَأَلْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَنْ ذَلِكَ، فَقَالَ: "إِنَّمَا يُجْزِيكَ مِنْ ذَلِكَ الْوُضُوءُ". قُلْتُ يَا رَسُولَ اللهِ، فَكَيْفَ بِمَا يُصِيبُ ثَوْبِي مِنْهُ؟ قَالَ: "يَكْفِيكَ بِأَنْ تَأْخُذَ كَفًّا مِنْ مَاءٍ، فَتَنْضَحَ بِهَا مِنْ ثَوْبِكَ حَيْثُ تَرَى أَنَّهُ أَصَابَهُ". (د,ت,جه)', 'സഹ്ലുബ്നു ഹുനൈഫ്(റ): എനിക്ക് പെട്ടെന്ന് കാമജലം (മദ്യ്) പുറപ്പെടുമായിരുന്നു. അതുകാരണം ഞാൻ കൂടുതൽ കുളിക്കുകയും ചെയ്തിരുന്നു. അങ്ങനെയിരിക്കെ (ഒരിക്കൽ) നബി(സ)യോട് ഇക്കാര്യത്തെക്കുറിച്ച് ചോദിച്ചു. നബി(സ) പറഞ്ഞു: "അതിന് വുദു മതി." ഞാൻ ചോദിച്ചു: അത് വസ്ത്രത്തിലായാലോ?. നബി(സ) പറഞ്ഞു: "മുൻകൈ നിറയെ വെള്ളമെടുത്ത് (മദ്യ്) ആയിട്ടുണ്ടെന്ന് നീ കരുതുന്ന സ്ഥലം കഴുകിയാൽ മതി." (ദ,തു,ജ)', 'سَهْلِ بْنِ حُنَيْفٍ', 'സഹ്ലുബ്നു ഹുനൈഫ്(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 146, 146, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 14, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَدِمَ أُنَاسٌ مِنْ عُكْلٍ أَوْ عُرَيْنَةَ، فَاجْتَوَوُا الْمَدِينَةَ فَأَمَرَهُمُ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِلِقَاحٍ، وَأَنْ يَشْرَبُوا مِنْ أَبْوَالِهَا وَأَلْبَانِهَا، فَانْطَلَقُوا، قَتَلُوا رَاعِيَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، وَاسْتَاقُوا النَّعَمَ، فَجَاءَ الْخَبَرُ فِي أَوَّلِ النَّهَارِ، فَبَعَثَ فِي آثَارِهِمْ، فَلَمَّا ارْتَفَعَ النَّهَارُ جِيءَ بِهِمْ، فَأَمَرَ فَقَطَعَ أَيْدِيَهُمْ وَأَرْجُلَهُمْ، وَسُمِرَتْ أَعْيُنُهُمْ، وَأُلْقُوا فِي الْحَرَّةِ، يَسْتَسْقُونَ فَلَا يُسْقَوْنَ. (ق,د,ت,جه)', 'അനസ്(റ): ഉക്ക്ൽ അല്ലെങ്കിൽ ഉറൈന ഗോത്രത്തിലെ ചിലർ മദീനയിലേക്ക് വന്നു. അവിടത്തെ കാലാവസ്ഥ അവർക്ക് പിടിച്ചില്ല. അവർ രോഗികളായി. അപ്പോൾ പാലുള്ള ഒട്ടകങ്ങളുള്ള സ്ഥലത്തേക്ക് പോകാനും അവയുടെ പാലും മൂത്രവും കഴിക്കാനും നബി(സ) ഉപദേശിച്ചു. അങ്ങനെ അവർ പോയി. അവർക്ക് സുഖമായപ്പോൾ നബി(സ)യുടെ ഒട്ടകങ്ങളെ മേക്കുന്നവനെ അവർ കൊല്ലുകയും ഒട്ടകങ്ങളുമായി പോകുകയും ചെയ്തു. പുലർച്ചെ തന്നെ നബി(സ)ക്ക് വിവരം ലഭിച്ചു. നബി(സ) അവരെ പിടിക്കാൻ ആളയച്ചു. സൂര്യൻ കുറെ പൊങ്ങിക്കഴിഞ്ഞപ്പോഴേക്ക് അവരെ കൊണ്ടുവന്നു. ഉടനെ അവരുടെ കൈകളും കാലുകളും മുറിക്കാനും കണ്ണുകൾ പൊട്ടിക്കാനും വെള്ളം ചോദിച്ചാൽ നൽകാതെ ചുട്ടുപഴുത്ത കല്ലിൽ കിടത്താനും കൽപിച്ചു. (ബു,മു,ദ,തു,ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസ്(റ)', null, null, array['ق','د','ت','جه']::text[], array['ബു','മു','ദ','തു','ജ']::text[], null, null, 146, 147, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 15, 'عَنْ أَبِي رَزِينٍ رَضِيَ اللهُ عَنْهُ قَالَ: رَأَيْتُ أَبَا هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ يَضْرِبُ جَبْهَتَهُ بِيَدِهِ وَيَقُولُ: يَا أَهْلَ الْعِرَاقِ، أَنْتُمْ تَزْعُمُونَ أَنِّي أَكْذِبُ عَلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، لِيَكُونَ لَكُمُ الْمَهْنَأُ وَعَلَيَّ الْإِثْمُ. أَشْهَدُ لَسَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "إِذَا وَلَغَ الْكَلْبُ فِي إِنَاءِ أَحَدِكُمْ فَلْيَغْسِلْهُ سَبْعَ مَرَّاتٍ". (ق,ن,جه)', 'അബൂറസീൻ(റ): അബൂഹുറൈറ(റ) സ്വന്തം കൈ കൊണ്ട് മുഖത്തടിച്ച് ഇങ്ങനെ പറയുന്നത് ഞാൻ കേട്ടു: ഇറാഖികളേ! എനിക്ക് പാപവും നിങ്ങൾക്ക് ആശ്വാസവും കിട്ടാൻ വേണ്ടി ഞാൻ അല്ലാഹുവിന്റെ ദൂതരിൽ നിന്ന് ഇല്ലാത്തത് പറയുന്നുവെന്ന് നിങ്ങൾ വാദിക്കുന്നു. തീർച്ചയായും അല്ലാഹുവിന്റെ ദൂതർ ഇങ്ങനെ പറയുന്നത് ഞാൻ കേട്ടിട്ടുണ്ടെന്ന് ഞാൻ സാക്ഷ്യം വഹിക്കുന്നു: "നിങ്ങളിൽ ആരുടെയെങ്കിലും പാത്രത്തിൽ നായ തലയിട്ടാൽ അത് ഏഴു പ്രാവശ്യം കഴുകണം." (ബു,മു,ന,ജ)', 'أَبِي رَزِينٍ', 'അബൂറസീൻ(റ)', null, null, array['ق','ن','جه']::text[], array['ബു','മു','ന','ജ']::text[], null, null, 147, 147, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 16, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ قَالَ: "لَا يَبُولَنَّ أَحَدُكُمْ فِي الْمَاءِ الدَّائِمِ الَّذِي لَا يَجْرِي، ثُمَّ يَغْتَسِلُ فِيهِ". (ق,ن)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "ഒഴുകാതെ കെട്ടിനിൽക്കുന്ന വെള്ളത്തിൽ മൂത്രമൊഴിക്കരുത്. (കാരണം) പിന്നീടവൻ അതിൽ തന്നെ കുളിക്കുകയും ചെയ്യും (ചെയ്യേണ്ടിവരും). (ബു,മു,ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','ن']::text[], array['ബു','മു','ന']::text[], null, null, 147, 147, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 17, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كُنْتُ أَغْسِلُ الْجَنَابَةَ مِنْ ثَوْبِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَيَخْرُجُ إِلَى الصَّلَاةِ، وَإِنَّ بُقَعَ الْمَاءِ فِي ثَوْبِهِ. (ق)', 'ആഇശ(റ): നബിയുടെ വസ്ത്രത്തിൽ നിന്ന് ഞാൻ ശുക്ലം കഴുകിക്കളയുകയും അവിടന്ന് ആ വസ്ത്രം ധരിച്ചു കൊണ്ട് നിസ്കാരത്തിന് പോവുകയും ചെയ്യാറുണ്ടായിരുന്നു. ആ വെള്ളം നനഞ്ഞ അടയാളം നബിയുടെ വസ്ത്രത്തിലുണ്ടായിരിക്കും. (ബു,മു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ق']::text[], array['ബു','മു']::text[], null, null, 147, 147, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 18, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "اتَّقُوا اللَّعَّانَيْنِ". قَالُوا: وَمَا اللَّعَّانَانِ يَا رَسُولَ اللهِ؟ قَالَ: "الَّذِي يَتَخَلَّى فِي طَرِيقِ النَّاسِ أَوْ فِي ظِلِّهِمْ". (م,د)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "(ജന) ശാപമേൽക്കേണ്ടി വരുന്ന രണ്ട് ചെയ്തികൾ നിങ്ങൾ സൂക്ഷിക്കുക." അവർ ചോദിച്ചു: "ശാപമേൽക്കേണ്ടി വരുന്ന സംഗതികളെന്താണ്?." നബി(സ) പറഞ്ഞു: "ജനങ്ങളുടെ വഴികളിലോ വിശ്രമ കേന്ദ്രങ്ങളിലോ വിസർജ്ജനം ചെയ്യുന്നവന്റെ (ചെയ്തികൾ!)." (മു,ദ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','د']::text[], array['മു','ദ']::text[], null, null, 147, 147, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 19, 'عَنْ مُعَاذِ بْنِ جَبَلٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "اتَّقُوا الْمَلَاعِنَ الثَّلَاثَةَ: الْبَرَازَ فِي الْمَوَارِدِ، وَقَارِعَةَ الطَّرِيقِ، وَالظِّلَّ". (د,جه)', 'മുആദ്(റ): നബി(സ) പറഞ്ഞു: "ശാപമേൽക്കുന്ന മൂന്ന് സ്ഥലങ്ങൾ നിങ്ങൾ കരുതിയിരിക്കുക. അതായത് ജനങ്ങളുടെ വഴിയിലും അവരുടെ തണലുകളിലും ഒലിപ്പു വെള്ളങ്ങൾക്കരികിലും വിസർജ്ജിക്കുന്നത് സൂക്ഷിക്കുക." (ദ,ജ)', 'مُعَاذِ بْنِ جَبَلٍ', 'മുആദ്(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 147, 147, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 20, 'عَنْ عَبْدِ اللهِ بْنِ جَعْفَرٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: أَرْدَفَنِي رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ ذَاتَ يَوْمٍ خَلْفَهُ، فَأَسَرَّ إِلَيَّ حَدِيثًا لَا أُحَدِّثُ بِهِ أَحَدًا مِنَ النَّاسِ، وَكَانَ أَحَبَّ مَا اسْتَتَرَ بِهِ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لِحَاجَتِهِ هَدَفٌ أَوْ حَائِشُ نَخْلٍ. قَالَ ابْنُ أَسْمَاءَ رَضِيَ اللهُ عَنْهُمَا فِي حَدِيثِهِ: يَعْنِي حَائِطَ نَخْلٍ. (م)', 'അബ്ദുല്ലാഹിബ്നു ജഅ്ഫർ(റ): നബി(സ) ഒരിക്കൽ തന്റെ വാഹനത്തിനു പിന്നിൽ എന്നെയും കൂട്ടി. അവിടുന്ന് എന്നോട് ഒരു ഹദീസ് രഹസ്യമായി പറഞ്ഞു തന്നു. അത് ഞാനാർക്കും പറഞ്ഞു കൊടുക്കില്ല. "(പ്രാഥമിക) ആവശ്യങ്ങൾക്കുവേണ്ടി മറഞ്ഞിരിക്കാൻ ഉയർന്നു നിൽക്കുന്ന എന്തെങ്കിലും വസ്തുക്കളോ ഈത്തപ്പനത്തോട്ടമോ ആയിരുന്നു നബി(സ)ക്ക് ഏറ്റവും ഇഷ്ടം." (മു)', 'عَبْدِ اللهِ بْنِ جَعْفَرٍ', 'അബ്ദുല്ലാഹിബ്നു ജഅ്ഫർ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 148, 148, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 21, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: مَرَّ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَلَى قَبْرَيْنِ، فَقَالَ: "أَمَا إِنَّهُمَا لَيُعَذَّبَانِ، وَمَا يُعَذَّبَانِ فِي كَبِيرٍ، أَمَّا أَحَدُهُمَا فَكَانَ يَمْشِي بِالنَّمِيمَةِ، وَأَمَّا الْآخَرُ فَكَانَ لَا يَسْتَتِرُ مِنْ بَوْلِهِ". قَالَ: فَدَعَا بِعَسِيبٍ رَطْبٍ، فَشَقَّهُ بِاثْنَيْنِ، ثُمَّ غَرَسَ عَلَى هَذَا وَاحِدًا وَعَلَى هَذَا وَاحِدًا، ثُمَّ قَالَ: "لَعَلَّهُ أَنْ يُخَفَّفَ عَنْهُمَا مَا لَمْ يَيْبَسَا". (ق,ن,ت,جه,د)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) രണ്ട് ഖബറുകൾക്കരികിലൂടെ നടന്നുപോയപ്പോൾ പറഞ്ഞു: "അറിയുക, ഈ രണ്ടു ഖബ്റിലുള്ളവർ ശിക്ഷിക്കപ്പെടുകയാണ്. (അവരുടെ വീക്ഷണത്തിൽ) ഒരു വലിയ കുറ്റത്തിന്റെ പേരിലൊന്നുമല്ല അവർ ശിക്ഷയനുഭവിക്കുന്നത്. ഒരാൾ ഏഷണിയുമായി നടക്കുന്നവനായിരുന്നു. അപരൻ വിസർജ്ജിക്കുമ്പോൾ മറ സ്വീകരിക്കാത്തവനായിരുന്നു." ഇബ്നുഅബ്ബാസ്(റ) പറയുന്നു: നബി(സ) ഒരു ഈത്തപ്പന മട്ടൽ ആവശ്യപ്പെടുകയും അതിനെ രണ്ടായി പിളർത്തുകയും ചെയ്തു. ഓരോന്നും ഓരോ ഖബ്റിന്മേലും കുഴിച്ചിട്ടശേഷം പറഞ്ഞു: "ഇവ ഉണങ്ങാതെ നിൽക്കുമ്പോഴെല്ലാം ഇവരുടെ ശിക്ഷയിൽ ലഘൂകരണം ലഭിച്ചേക്കാം." (ബു,മു,ദ,തു,ന,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ق','ن','ت','جه','د']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 148, 148, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 22, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ أَزْوَاجَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ – كُنَّ يَخْرُجْنَ بِاللَّيْلِ إِذَا تَبَرَّزْنَ إِلَى الْمَنَاصِعِ، وَهُوَ صَعِيدٌ أَفْيَحُ، فَكَانَ عُمَرُ رَضِيَ اللهُ عَنْهُ يَقُولُ لِلنَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: احْجُبْ نِسَاءَكَ، فَلَمْ يَكُنْ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَفْعَلُ، فَخَرَجَتْ سَوْدَةُ بِنْتُ زَمْعَةَ رَضِيَ اللهُ عَنْهَا، زَوْجُ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لَيْلَةً مِنَ اللَّيَالِي عِشَاءً، وَكَانَتِ امْرَأَةً طَوِيلَةً، فَنَادَاهَا عُمَرُ رَضِيَ اللهُ عَنْهُ: أَلَا قَدْ عَرَفْنَاكِ يَا سَوْدَةُ، حِرْصًا عَلَى أَنْ يَنْزِلَ الْحِجَابُ، فَأَنْزَلَ اللهُ آيَةَ الْحِجَابِ. (ق)', 'ആഇശ(റ): നബി(സ)യുടെ ഭാര്യമാർ വെളിക്കിരിക്കാനുണ്ടാകുമ്പോൾ രാത്രിയിൽ മനാസിഇ (ബഖീഇനടുത്തുള്ള വിശാലമായ സ്ഥലം)ലേക്ക് പോകാറുണ്ടായിരുന്നു. എന്നാൽ തങ്ങളുടെ ഭാര്യമാരോട് മറ സ്വീകരിക്കാൻ കൽപിക്കണമെന്ന് നബി(സ)യോട് ഉമർ(റ) പറയാറുണ്ടായിരുന്നു. എന്നാൽ നബി(സ) അത് ചെയ്തിരുന്നില്ല. നബി(സ)യുടെ ഭാര്യയും സംഅത്തിന്റെ മകളുമായ സൗദ(റ) ഒരു രാത്രി ഇശാസമയത്ത് പുറത്തിറങ്ങി. അവർ പൊക്കമുള്ള സ്ത്രീയായിരുന്നു. ഹിജാബിന്റെ വിധി ഇറങ്ങാനുള്ള ആഗ്രഹത്തോടെ ഉമർ(റ) പറഞ്ഞു: ''സൗദാ നിന്നെ ഞാൻ അറിഞ്ഞിരിക്കുന്നു.'' അപ്പോൾ ഹിജാബിന്റെ (സ്ത്രീ വസ്ത്ര ധാരണം) സൂക്തം അവതരിച്ചു. (ബു,മു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ق']::text[], array['ബു','മു']::text[], null, null, 148, 148, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 23, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا أَرَادَ حَاجَةً لَا يَرْفَعُ ثَوْبَهُ حَتَّى يَدْنُوَ مِنَ الْأَرْضِ. (د,ت)', 'ഇബ്നുഉമർ(റ): നബി(സ) വിസർജ്ജിക്കാനുദ്ദേശിക്കുമ്പോൾ നിലത്തോടടുക്കുമ്പോഴല്ലാതെ വസ്ത്രം ഉയർത്താറുണ്ടായിരുന്നില്ല. (ദ,തു)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 148, 148, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 24, 'عَنْ أَبِي سَعِيدٍ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "لَا يَخْرُجُ الرَّجُلَانِ يَضْرِبَانِ الْغَائِطَ، كَاشِفَيْنِ عَنْ عَوْرَتِهِمَا، يَتَحَدَّثَانِ، فَإِنَّ اللهَ عَزَّ وَجَلَّ يَمْقُتُ عَلَى ذَلِكَ". (د,ت,جه)', 'അബൂസഈദ്(റ): നബി(സ) പറയുന്നതായി ഞാൻ കേട്ടു: "നഗ്നത വെളിപ്പെടുത്തിയും സംസാരിച്ചും രണ്ടുപേർ ഒന്നിച്ച് മലവിസർജ്ജനത്തിന് പുറപ്പെടരുത്. നിശ്ചയം അല്ലാഹു അതുകാരണം കോപിക്കുന്നതാണ്." (ദ,തു,ജ)', 'أَبِي سَعِيدٍ', 'അബൂസഈദ്(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 149, 149, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 25, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا يَتَنَاجَى اثْنَانِ عَلَى غَائِطِهِمَا، يَنْظُرُ كُلُّ وَاحِدٍ مِنْهُمَا إِلَى عَوْرَةِ صَاحِبِهِ، فَإِنَّ اللهَ عَزَّ وَجَلَّ يَمْقُتُ عَلَى ذَلِكَ". (د,جه)', 'അബൂസഈദ്(റ): നബി(സ) പറഞ്ഞു: "മലവിസർജ്ജനം ചെയ്യവെ, പരസ്പരം നഗ്നത നോക്കിയിരുന്ന് രണ്ടാളുകൾ സംസാരിക്കരുത്. തീർച്ചയായും അല്ലാഹു അത് കാരണം കോപിക്കും. (ശിക്ഷിക്കും)." (ദ,ജ)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദ്(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 149, 149, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 26, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: مَرَّ رَجُلٌ عَلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَهُوَ يَبُولُ، فَسَلَّمَ عَلَيْهِ، فَلَمْ يَرُدَّ عَلَيْهِ. (م,د,ت,ن,جه)', 'ഇബ്നുഉമർ(റ): നബി(സ) മൂത്രമൊഴിച്ചു കൊണ്ടിരിക്കെ അതു വഴി കടന്നുപോയ ഒരാൾ നബിക്ക് സലാം ചൊല്ലി. എന്നാൽ നബി(സ) സലാം മടക്കിയില്ല. (മു,ദ,തു,ന,ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['م','د','ت','ن','جه']::text[], array['മു','ദ','തു','ന','ജ']::text[], null, null, 149, 149, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 27, 'عَنِ الْمُهَاجِرِ بْنِ قُنْفُذٍ رَضِيَ اللهُ عَنْهُ: أَنَّهُ أَتَى النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَهُوَ يَبُولُ، فَسَلَّمَ عَلَيْهِ، فَلَمْ يَرُدَّ عَلَيْهِ حَتَّى تَوَضَّأَ، ثُمَّ اعْتَذَرَ إِلَيْهِ فَقَالَ: "إِنِّي كَرِهْتُ أَنْ أَذْكُرَ اللهَ عَزَّ وَجَلَّ إِلَّا عَلَى طُهْرٍ. أَوْ قَالَ: عَلَى طَهَارَةٍ". (د,ن,جه)', 'മുഹാജിറുബ്നു ഖുൻഫുദ(റ): അദ്ദേഹം മൂത്രമൊഴിച്ചു കൊണ്ടിരിക്കുക്കുകയായിരുന്ന നബി(സ)യെ അദ്ദേഹം സമീപിച്ചു സലാം ചൊല്ലി. എന്നാൽ വുദു ചെയ്യാതെ നബി(സ) സലാം മടക്കിയില്ല. തുടർന്ന് നബി(സ) കാരണം പറഞ്ഞു: "ശുദ്ധിയോട് കൂടെയല്ലാതെ അല്ലാഹുവിനെ സ്മരിക്കുന്നത് ഞാൻ വെറുക്കുന്നു." (ദ,ന,ജ)', 'الْمُهَاجِرِ بْنِ قُنْفُذٍ', 'മുഹാജിറുബ്നു ഖുൻഫുദ(റ)', null, null, array['د','ن','جه']::text[], array['ദ','ന','ജ']::text[], null, null, 149, 149, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 28, 'عَنْ عَبْدِ اللهِ بْنِ مُغَفَّلٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا يَبُولَنَّ أَحَدُكُمْ فِي مُسْتَحَمِّهِ ثُمَّ يَغْتَسِلُ فِيهِ – وَفِي رِوَايَةٍ: ثُمَّ يَتَوَضَّأُ فِيهِ – فَإِنَّ عَامَّةَ الْوَسْوَاسِ مِنْهُ". (د,ت,ن,جه)', 'അബ്ദുല്ലാഹിബ്നു മുഗഫഫൽ(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങളിലൊരാളും കുളിമുറിയിൽ മൂത്രമൊഴിക്കുകയും പിന്നെ അവിടെ വെച്ചുതന്നെ കുളിക്കുകയും ചെയ്യരുത്. (മറ്റൊരു റിപ്പോർട്ടിൽ: പിന്നെ അവിടെ വെച്ച് വുളു ചെയ്യുകയും എന്നാണ്.) കാരണം മിക്ക മനഃശല്യവും (വസ്വാസ്) അതിൽ നിന്നാണ് ഉത്ഭവിക്കുന്നത്." (ദ,തു,ന,ജ)', 'عَبْدِ اللهِ بْنِ مُغَفَّلٍ', 'അബ്ദുല്ലാഹിബ്നു മുഗഫഫൽ(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 149, 149, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=10 and h.hadith_no=28), 1, 'وَفِي رِوَايَةٍ: ثُمَّ يَتَوَضَّأُ فِيهِ – فَإِنَّ عَامَّةَ الْوَسْوَاسِ مِنْهُ". (د,ت,ن,جه)', 'മറ്റൊരു നിവേദനിൽ: പിന്നെ അവിടെ വെച്ച് വുളു ചെയ്യുകയും എന്നാണ്.) കാരണം മിക്ക മനഃശല്യവും (വസ്വാസ്) അതിൽ നിന്നാണ് ഉത്ഭവിക്കുന്നത്." (ദ,തു,ന,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 29, 'عَنْ عَبْدِ اللهِ بْنِ سَرْجِسَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ نَهَى أَنْ يُبَالَ فِي الْجُحْرِ. (د,ن)', 'അബ്ദുല്ലാഹിബ്നു സർജസ്(റ): നബി(സ) മാളത്തിൽ മൂത്രമൊഴിക്കുന്നത് നിരോധിച്ചിരിക്കുന്നു. (ദ,ന)', 'عَبْدِ اللهِ بْنِ سَرْجِسَ', 'അബ്ദുല്ലാഹിബ്നു സർജസ്(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 149, 149, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 30, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِذَا دَخَلَ الْخَلَاءَ قَالَ: "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْخُبُثِ وَالْخَبَائِثِ". (ق)', 'അനസ്(റ): റസൂൽ(സ) വിസർജ്ജന സ്ഥലത്ത് പ്രവേശിക്കുമ്പോൾ; "അല്ലാഹുവേ, ആൺപിശാചുക്കളിൽ നിന്നും പെൺ പിശാചുക്കളിൽ നിന്നും ഞാൻ നിന്നിൽ ശരണം തേടുന്നു." എന്നു പറയാറുണ്ടായിരുന്നു. (ബു,മു)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ق']::text[], array['ബു','മു']::text[], null, null, 149, 149, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 31, 'عَنْ أَبِي أَيُّوبَ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِذَا أَتَيْتُمُ الْغَائِطَ فَلَا تَسْتَقْبِلُوا الْقِبْلَةَ وَلَا تَسْتَدْبِرُوهَا، بِبَوْلٍ وَلَا غَائِطٍ، وَلَكِنْ شَرِّقُوا أَوْ غَرِّبُوا". قَالَ أَبُو أَيُّوبَ: فَقَدِمْنَا الشَّامَ فَوَجَدْنَا مَرَاحِيضَ قَدْ بُنِيَتْ قِبَلَ الْقِبْلَةِ، فَنَنْحَرِفُ عَنْهَا، وَنَسْتَغْفِرُ اللهَ. (م,ت,ن,جه)', 'അബൂഅയ്യൂബ്(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങൾ വിസർജ്ജനസ്ഥലത്തെത്തിയാൽ ഖിബ്ലയെ മുന്നിടുകയോ പിന്നിടുകയോ ചെയ്തുകൊണ്ട് മൂത്രമൊഴിക്കുകയോ മലവിസർജ്ജനം നടത്തുകയോ അരുത്. എന്നാൽ നിങ്ങൾ കിഴക്കോട്ടോ പടിഞ്ഞാറോട്ടോ⁵ തിരിഞ്ഞിരിക്കുക." അബൂഅയ്യൂബ്(റ) പറയുന്നു: ഞങ്ങൾ സിറിയയിൽ ചെന്നപ്പോൾ ഖിബ്ലക്കഭിമുഖമായി നിർമ്മിക്കപ്പെട്ട വിസർജ്ജന സ്ഥലങ്ങൾ കണ്ടു. ഞങ്ങൾ തെറ്റിയിരുന്ന് വിസർജ്ജിച്ചു. അല്ലാഹുവോട് പാപമോചനം തേടുകയും ചെയ്തു. (മു,തു,ന,ജ)', 'أَبِي أَيُّوبَ', 'അബൂഅയ്യൂബ്(റ)', null, null, array['م','ت','ن','جه']::text[], array['മു','തു','ന','ജ']::text[], null, null, 150, 150, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 32, 'عَنْ أَبِي أَيُّوبَ الْأَنْصَارِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِذَا أَتَى أَحَدُكُمُ الْغَائِطَ فَلَا يَسْتَقْبِلِ الْقِبْلَةَ وَلَا يُوَلِّهَا ظَهْرَهُ، شَرِّقُوا أَوْ غَرِّبُوا". (ق)', 'അബൂഅയ്യൂബുൽ അൻസാരി(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങളിലൊരാൾ വിസർജ്ജന സ്ഥലത്ത് ചെന്നാൽ ഖിബ്ലക്ക് മുന്നിടുകയോ പിന്നിടുകയോ ചെയ്യരുത്. നിങ്ങൾ കിഴക്കോട്ടോ പടിഞ്ഞാറോട്ടോ തിരിയുക. (ബു,മു)', 'أَبِي أَيُّوبَ الْأَنْصَارِيِّ', 'അബൂഅയ്യൂബുൽ അൻസാരി(റ)', null, null, array['ق']::text[], array['ബു','മു']::text[], null, null, 150, 150, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 33, 'عَنْ عَبْدِ اللهِ بْنِ أَبِي قَتَادَةَ عَنْ أَبِيهِ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا يُمْسِكَنَّ أَحَدُكُمْ ذَكَرَهُ بِيَمِينِهِ وَهُوَ يَبُولُ، وَلَا يَتَمَسَّحْ مِنَ الْخَلَاءِ بِيَمِينِهِ، وَلَا يَتَنَفَّسْ فِي الْإِنَاءِ". (م)', 'ഖതാദ(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങളാരും മൂത്രമൊഴിക്കുമ്പോൾ വലതുകൈ കൊണ്ട് ലിംഗം തൊടുകയോ ശൗച്യം ചെയ്യുകയോ ചെയ്യരുത്. കുടിക്കുമ്പോൾ പാത്രത്തിലേക്ക് ശ്വാസം വിടുകയും അരുത്. (മു)', 'عَبْدِ اللهِ بْنِ أَبِي قَتَادَةَ عَنْ أَبِيهِ', 'ഖതാദ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 150, 150, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 34, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ دَخَلَ حَائِطًا وَتَبِعَهُ غُلَامٌ وَمَعَهُ مِيضَأَةٌ، هُوَ أَصْغَرُنَا، فَوَضَعَهَا عِنْدَ سِدْرَةٍ، فَقَضَى رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ حَاجَتَهُ فَخَرَجَ عَلَيْنَا وَقَدِ اسْتَنْجَى بِالْمَاءِ. (م,د,جه)', 'അനസുബ്നു മാലിക്(റ): നബി(സ) ഒരു തോട്ടത്തിൽ പ്രവേശിച്ചു. ഞങ്ങളിലെ ഒരു ചെറിയ കുട്ടി വെള്ളപ്പാത്രവുമായി നബി(സ)യെ പിന്തുടർന്നു. വെള്ളപ്പാത്രം ഒരു ഇലന്ത മരത്തിന്റെ അടുത്തുവെച്ചു. വിസർജ്ജനം കഴിഞ്ഞശേഷം നബി(സ) വെള്ളം കൊണ്ട് ശുദ്ധിയാക്കി. (മു,ദ,ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['م','د','جه']::text[], array['മു','ദ','ജ']::text[], null, null, 150, 150, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 35, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ – يَبْلُغُ بِهِ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ – قَالَ: "إِذَا اسْتَجْمَرَ أَحَدُكُمْ فَلْيَسْتَجْمِرْ وِتْرًا، وَإِذَا تَوَضَّأَ أَحَدُكُمْ فَلْيَجْعَلْ فِي أَنْفِهِ مَاءً ثُمَّ لِيَنْثُرْ". (م)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങൾ കല്ലു കൊണ്ട് ശൗച്യം ചെയ്യുമ്പോൾ ഒറ്റയിൽ അവസാനിപ്പിക്കുക. വുദു ചെയ്യുമ്പോൾ മൂക്കിൽ വെള്ളം കയറ്റിച്ചീറ്റുകയും വേണം." (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 150, 150, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 36, 'عَنْ حُذَيْفَةَ رَضِيَ اللهُ عَنْهُ قَالَ: أَتَى رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ سُبَاطَةَ قَوْمٍ فَبَالَ قَائِمًا، ثُمَّ دَعَا بِمَاءٍ فَمَسَحَ عَلَى خُفَّيْهِ. وَفِي رِوَايَةٍ قَالَ: فَذَهَبْتُ أَتَبَاعَدُ، فَدَعَانِي حَتَّى كُنْتُ عِنْدَ عَقِبِهِ. (ق,د,ت,ن,جه)', 'ഹുദൈഫ(റ): ഒരു ജനതയുടെ കുപ്പയിൽ (പറമ്പിൽ) നബി(സ) ചെന്നപ്പോൾ നിന്ന് മൂത്രമൊഴിച്ചു.⁶ തുടർന്ന് വെള്ളം ആവശ്യപ്പെട്ടു. അപ്പോൾ രണ്ടു ഖുഫ്ഫമേൽ തടവി. മറ്റൊരു റിപ്പോർട്ടിൽ: ഞാൻ അദ്ദേഹത്തിൽ നിന്ന് അകന്നുപോയി. നബി(സ) എന്നെ അദ്ദേഹത്തിന്റെ ചുമലിന്നടുത്തെത്തുന്നതു വരെ (അടുത്തേക്ക്) വിളിച്ചു. (ബു,മു,ദ,തു,ന,ജ)', 'حُذَيْفَةَ', 'ഹുദൈഫ(റ)', '⁵. മദീനക്കാരോടാണ് തിരുനബി(സ) ഇത് നിർദ്ദേശിക്കുന്നത്. മക്കയുടെ വടക്കുഭാഗത്താണ് മദീന സ്ഥിതിചെയ്യുന്നത്.
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=10 and h.hadith_no=36), 1, 'وَفِي رِوَايَةٍ قَالَ: فَذَهَبْتُ أَتَبَاعَدُ، فَدَعَانِي حَتَّى كُنْتُ عِنْدَ عَقِبِهِ. (ق,د,ت,ن,جه)', 'മറ്റൊരു നിവേദനിൽ: ഞാൻ അദ്ദേഹത്തിൽ നിന്ന് അകന്നുപോയി. നബി(സ) എന്നെ അദ്ദേഹത്തിന്റെ ചുമലിന്നടുത്തെത്തുന്നതു വരെ (അടുത്തേക്ക്) വിളിച്ചു. (ബു,മു,ദ,തു,ന,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 37, 'عَنْ أُمَيْمَةَ بِنْتِ رُقَيْقَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كَانَ لِلنَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَدَحٌ مِنْ عِيدَانٍ تَحْتَ سَرِيرِهِ يَبُولُ فِيهِ بِاللَّيْلِ. (د,ن)', 'റുഖൈഖയുടെ മകൾ ഉമൈമ(റ): നബി(സ)ക്ക് അവിടുത്തെ കട്ടിലിനു ചുവട്ടിൽ ഒരു മരച്ചട്ടിയുണ്ടായിരുന്നു. അവിടുന്ന് രാത്രി അതിൽ മൂത്രമൊഴിക്കുമായിരുന്നു. (ദ,ന)', 'أُمَيْمَةَ بِنْتِ رُقَيْقَةَ', 'റുഖൈഖയുടെ മകൾ ഉമൈമ(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 151, 151, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 38, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: مَنْ حَدَّثَكُمْ أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بَالَ قَائِمًا فَلَا تُصَدِّقُوهُ، مَا كَانَ يَبُولُ إِلَّا جَالِسًا. (ن)', 'ആഇശ(റ): നബി(സ) നിന്നുകൊണ്ട് മൂത്രമൊഴിച്ചുവെന്ന് ആരെങ്കിലും നിങ്ങളോട് പറഞ്ഞാൽ അയാളെ നിങ്ങൾ വിശ്വസിക്കരുത്. നബി(സ) ഇരുന്നല്ലാതെ മൂത്രിക്കാറില്ല. (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 151, 151, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 39, 'جَابِرِ بْنِ عَبْدِ اللهِ رَضِيَ اللهُ عَنْهُمَا قَالَ: نَهَانَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنْ نَتَمَسَّحَ بِعَظْمٍ أَوْ بَعْرٍ. (م,د)', 'ജാബിറുബ്നുഅബ്ദില്ല(റ): എല്ലു കൊണ്ടോ കാഷ്ഠം കൊണ്ടോ ശുദ്ധിയാക്കുന്നത് നബി(സ) നിരോധിച്ചിരിക്കുന്നു. (മു,ദ)', null, 'ജാബിറുബ്നുഅബ്ദില്ല(റ)', null, null, array['م','د']::text[], array['മു','ദ']::text[], null, null, 151, 151, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 40, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ تَوَضَّأَ، فَلَمَّا اسْتَنْجَى دَلَكَ يَدَهُ بِالْأَرْضِ. (ن,د)', 'അബൂഹുറൈറ(റ): നബി(സ) വുദു ചെയ്തു. ശൗച്യം ചെയ്തു കഴിഞ്ഞപ്പോൾ തന്റെ കൈ മണ്ണിൽ ഉരസി. (ദ,ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ن','د']::text[], array['ദ','ന']::text[], null, null, 151, 151, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 41, 'عَنْ سَلْمَانَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ لَهُ رَجُلٌ: إِنَّ صَاحِبَكُمْ لَيُعَلِّمُكُمْ حَتَّى الْخِرَاءَةَ. قَالَ: أَجَلْ، نَهَانَا أَنْ نَسْتَقْبِلَ الْقِبْلَةَ بِغَائِطٍ أَوْ بَوْلٍ، أَوْ نَسْتَنْجِيَ بِأَيْمَانِنَا، أَوْ نَكْتَفِيَ بِأَقَلَّ مِنْ ثَلَاثَةِ أَحْجَارٍ. (م,د,ن,جه)', 'സൽമാൻ(റ): ഒരാൾ അദ്ദേഹത്തോട് ചോദിച്ചു: മലവിസർജ്ജനം എങ്ങനെയെന്നുപോലും നിങ്ങളുടെ ആൾ (നബി) നിങ്ങൾക്ക് പഠിപ്പിച്ചു തരുന്നുണ്ടല്ലേ? അദ്ദേഹം പറഞ്ഞു: അതെ! മലമൂത്ര വിസർജ്ജനം ചെയ്യുമ്പോൾ ഖിബ്ലക്ക് മുന്നിടുകയോ പിന്നിടുകയോ ചെയ്യുന്നതും വലതുകൈ കൊണ്ട് ശൗച്യം ചെയ്യുന്നതും മൂന്നിൽ കുറഞ്ഞ കല്ലുകൾ കൊണ്ട് മതിയാക്കുന്നതുമൊക്കെ അവിടുന്ന് ഞങ്ങളോട് നിരോധിച്ചിരിക്കുന്നു. (മു,ദ,ന,ജ)', 'سَلْمَانَ', 'സൽമാൻ(റ)', null, null, array['م','د','ن','جه']::text[], array['മു','ദ','ന','ജ']::text[], null, null, 151, 151, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 42, 'عَنْ عَبْدِ اللهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ قَالَ: أَتَى النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ الْغَائِطَ، وَأَمَرَنِي أَنْ آتِيَهُ بِثَلَاثَةِ أَحْجَارٍ، فَوَجَدْتُ حَجَرَيْنِ، وَالْتَمَسْتُ الثَّالِثَ فَلَمْ أَجِدْهُ، فَأَخَذْتُ رَوْثَةً، فَأَتَيْتُ بِهِنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَأَخَذَ الْحَجَرَيْنِ وَأَلْقَى الرَّوْثَةَ، وَقَالَ: "هَذِهِ رِكْسٌ". (ق,ن)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): നബി(സ) വിസർജ്ജനത്തിന് പോവുകയും എന്നോട് മൂന്ന് കല്ലുകൾ കൊണ്ടുവരാൻ കൽപിക്കുകയും ചെയ്തു. എനിക്ക് രണ്ട് കല്ല് കിട്ടി. മൂന്നാമത്തെ കല്ലിനുവേണ്ടി തിരഞ്ഞുവെങ്കിലും കിട്ടിയില്ല. അപ്പോൾ ഞാൻ ഒരു ഉണക്കക്കാഷ്ഠം എടുത്തു. അവയുമായി നബി(സ)യുടെ അടുക്കൽ ചെന്നു. നബി(സ) കല്ലുകൾ എടുത്തു. ഉണക്കക്കാഷ്ഠം ഉപേക്ഷിച്ചു. തുടർന്ന് പറഞ്ഞു: "ഇത് അശുദ്ധമാണ്." (ബു,മു,ന)', 'عَبْدِ اللهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['ق','ن']::text[], array['ബു','മു','ന']::text[], null, null, 151, 151, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 43, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِذَا تَوَضَّأَ أَحَدُكُمْ فَلْيَجْعَلْ فِي أَنْفِهِ ثُمَّ لِيَنْثُرْ، وَمَنِ اسْتَجْمَرَ فَلْيُوتِرْ، وَإِذَا اسْتَيْقَظَ أَحَدُكُمْ مِنْ نَوْمِهِ فَلْيَغْسِلْ يَدَهُ قَبْلَ أَنْ يُدْخِلَهَا فِي وَضُوئِهِ، فَإِنَّ أَحَدَكُمْ لَا يَدْرِي أَيْنَ بَاتَتْ يَدُهُ". (ق)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങളിലാരെങ്കിലും വുദു ചെയ്താൽ അവൻ ജലനേതിക്രിയ (മൂക്കിൽ വെള്ളം കയറ്റിച്ചീറ്റൽ) ചെയ്യട്ടെ. ആരെങ്കിലും കല്ലു കൊണ്ട് ശൗച്യം ചെയ്യുന്ന പക്ഷം ഒറ്റയായ എണ്ണം ഉപയോഗിക്കട്ടെ. ഉറക്കത്തിൽ നിന്നുണർന്നാൽ വുദുവിന്റെ വെള്ളത്തിൽ കൈയിടുന്നതിനു മുമ്പ് തന്റെ കൈ കഴുകട്ടെ. കാരണം അവന്റെ കൈ രാത്രി എവിടെയാണ് വെച്ചിരുന്നതെന്ന് അവനറിയില്ല!." (ബു,മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق']::text[], array['ബു','മു']::text[], null, null, 151, 152, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 44, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: مَرَّ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِحَائِطٍ مِنْ حِيطَانِ الْمَدِينَةِ أَوْ مَكَّةَ، فَسَمِعَ صَوْتَ إِنْسَانَيْنِ يُعَذَّبَانِ فِي قُبُورِهِمَا، فَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "يُعَذَّبَانِ، وَمَا يُعَذَّبَانِ فِي كَبِيرٍ". ثُمَّ قَالَ: "بَلَى، كَانَ أَحَدُهُمَا لَا يَسْتَتِرُ مِنْ بَوْلِهِ، وَكَانَ الْآخَرُ يَمْشِي بِالنَّمِيمَةِ". ثُمَّ دَعَا بِجَرِيدَةٍ، فَكَسَرَهَا كِسْرَتَيْنِ، فَوَضَعَ عَلَى كُلِّ قَبْرٍ مِنْهُمَا كِسْرَةً، فَقِيلَ لَهُ: يَا رَسُولَ اللهِ، لِمَ فَعَلْتَ هَذَا؟ قَالَ: "لَعَلَّهُ أَنْ يُخَفَّفَ عَنْهُمَا مَا لَمْ تَيْبَسَا أَوْ إِلَى أَنْ يَيْبَسَا". (ق)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) മദീനയിലെയോ മക്കയിലെയോ ഒരു മതിലിന്നരികിലൂടെ നടന്നുപോയപ്പോൾ രണ്ട് മനുഷ്യരുടെ ശബ്ദം കേട്ടു. അവരിരുവരും ഖബ്റുകളിൽ ശിക്ഷിക്കപ്പെടുകയായിരുന്നു. നബി(സ) പറഞ്ഞു: "ആ രണ്ടുപേരും ശിക്ഷിക്കപ്പെടുകയാണ്, അവർ ശിക്ഷയനുഭവിക്കുന്നത് (അവരുടെ വീക്ഷണത്തിൽ) വലിയ കുറ്റത്തിനൊന്നുമല്ല. ഒരാൾ മലമൂത്ര വിസർജ്ജനം ചെയ്യുമ്പോൾ മറ സ്വീകരിച്ചിരുന്നില്ല. മറ്റവൻ ഏഷണിയും കൊണ്ട് നടക്കുന്നവനായിരുന്നു. അനന്തരം നബി(സ) ഈത്തപ്പനയുടെ ഒരു പച്ചപ്പട്ട കൊണ്ടുവരാനാവശ്യപ്പെട്ടു. അതു രണ്ടായി ചീന്തി ഓരോ ചീന്ത് ഓരോ ഖബ്റിന്റെ മുകളിൽ വെച്ചു. അല്ലാഹുവിന്റെ ദൂതരെ, എന്തിനാണ് താങ്കൾ അപ്രകാരം ചെയ്തതെന്നു ചിലർ അവിടത്തോട് ചോദിച്ചു. നബി(സ) പറഞ്ഞു: "അത് ഉണങ്ങുന്നതുവരെ രണ്ടാളുടെയും ശിക്ഷ ലഘൂകരിക്കപ്പെട്ടേക്കാം." (ബു,മു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ق']::text[], array['ബു','മു']::text[], null, null, 152, 152, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 45, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِذَا خَرَجَ مِنَ الْغَائِطِ قَالَ: "غُفْرَانَكَ". (د,ت,جه)', 'ആഇശ(റ): നബി(സ) വിസർജ്ജന സ്ഥലത്ത് നിന്നു വരുമ്പോൾ ''നിന്നോട് ഞാൻ മാപ്പപേക്ഷിക്കുന്നു.'' എന്ന് പ്രാർത്ഥിക്കാറുണ്ടായിരുന്നു. (ദ,തു,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 152, 152, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 46, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: أَمَرَنَا النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنْ نُوكِيَ أَسْقِيَتَنَا وَنُغَطِّيَ آنِيَتَنَا. (جه)', 'ജാബിർ(റ): ഞങ്ങളുടെ വെള്ളപ്പാത്രങ്ങളുടെ വായ് കെട്ടിവെക്കാനും പാത്രങ്ങൾ അടച്ചുവെക്കാനും നബി(സ) ഞങ്ങളോട് കൽപിച്ചു. (ജ)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 152, 152, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 47, 'عَنْ وَاسِعِ بْنِ حَبَّانَ رَضِيَ اللهُ عَنْهُ قَالَ: كُنْتُ أُصَلِّي فِي الْمَسْجِدِ، وَعَبْدُ اللهِ بْنُ عُمَرَ مُسْنِدٌ ظَهْرَهُ إِلَى الْقِبْلَةِ، فَلَمَّا قَضَيْتُ صَلَاتِي انْصَرَفْتُ إِلَيْهِ مِنْ شِقِّي، فَقَالَ عَبْدُ اللهِ: يَقُولُ أُنَاسٌ: إِذَا قَعَدْتَ لِلْحَاجَةِ تَكُونُ لَكَ، فَلَا تَقْعُدْ مُسْتَقْبِلَ الْقِبْلَةِ وَلَا بَيْتَ الْمَقْدِسِ، قَالَ عَبْدُ اللهِ: وَلَقَدْ رَقِيتُ عَلَى ظَهْرِ بَيْتٍ، فَرَأَيْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَاعِدًا عَلَى لَبِنَتَيْنِ، مُسْتَقْبِلًا بَيْتَ الْمَقْدِسِ لِحَاجَتِهِ. (م)', 'വാസിഉബ്നു ഹബ്ബാൻ(റ): ഞാൻ പള്ളിയിൽ നിസ്കരിക്കുമ്പോൾ അബ്ദുല്ലാഹിബ്നു ഉമർ(റ) ഖിബ്ലയിലേക്ക് ചാരിയിരിക്കുകയായിരുന്നു. നിസ്കാരശേഷം ഞാൻ എന്റെ ഭാഗത്തുകൂടി ഇബ്നുഉമർ(റ)ന്റെ അടുത്തേക്കു പോയി. അദ്ദേഹം പറഞ്ഞു: ജനങ്ങൾ പറയുന്നു: മലമൂത്ര വിസർജനത്തിന്നിരുന്നാൽ ഖിബ്ലക്കോ ബൈതുൽ മുഖദ്ദസിലേക്കോ മുന്നിട്ടിരിക്കരുത്. അബ്ദുല്ല(റ) പറഞ്ഞു: ഞാനൊരു വീടിന്റെ മുകളിൽ കയറി, നബി(സ) രണ്ട് ഇഷ്ടികകൾക്കു മുകളിൽ കയറിനിന്ന് ബൈതുൽ മുഖദ്ദസിലേക്കു തിരിഞ്ഞ് വിസർജ്ജിക്കാനിരിക്കുന്നതു ഞാൻ കണ്ടു. (മു)', 'وَاسِعِ بْنِ حَبَّانَ', 'വാസിഉബ്നു ഹബ്ബാൻ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 152, 152, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 48, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: تُصُدِّقَ عَلَى مَوْلَاةٍ لِمَيْمُونَةَ بِشَاةٍ فَمَاتَتْ، فَمَرَّ بِهَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "هَلَّا أَخَذْتُمْ إِهَابَهَا فَدَبَغْتُمُوهُ فَانْتَفَعْتُمْ بِهِ". فَقَالُوا: إِنَّهَا مَيْتَةٌ، فَقَالَ: "إِنَّمَا حَرُمَ أَكْلُهَا". (م)', 'ഇബ്നുഅബ്ബാസ്(റ): മൈമൂന(റ)യുടെ അടിമക്ക് ഒരു ആടിനെ സമ്മാനിക്കപ്പെടുകയും അത് ചത്തുപോവുകയും ചെയ്തു. നബി(സ) അതിനരികിൽ കൂടി നടന്നു. എന്നിട്ടു പറഞ്ഞു: "നിങ്ങൾക്ക് അതിന്റെ തോലെടുത്ത് ഊറക്കിട്ട് ഉപയോഗിച്ചു കൂടെയോ?" അവർ പറഞ്ഞു: അത് ശവമല്ലേ? നബി(സ) പറഞ്ഞു: "ശവം തിന്നലാണ് നിഷിദ്ധം." (മു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 153, 153, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 49, 'عَنْ يَزِيدَ بْنِ أَبِي حَبِيبٍ رَضِيَ اللهُ عَنْهُ: أَنَّ أَبَا الْخَيْرِ حَدَّثَهُ قَالَ: رَأَيْتُ عَلَى ابْنِ وَعْلَةَ السَّبَإِيِّ فَرْوًا، فَمَسِسْتُهُ، فَقَالَ: مَا لَكَ تَمَسُّهُ؟ قَدْ سَأَلْتُ عَبْدَ اللهِ بْنَ عَبَّاسٍ قُلْتُ: إِنَّا نَكُونُ بِالْمَغْرِبِ، وَمَعَنَا الْبَرْبَرُ وَالْمَجُوسُ، نُؤْتَى بِالْكَبْشِ قَدْ ذَبَحُوهُ نُؤْتَى بِالْكَبْشِ قَدْ ذَبَحُوهُ،وَنَحْنُ لَا نَأْكُلُ ذَبَائِحَهُمْ، وَيَأْتُونَا بِالسِّقَاءِ يَجْعَلُونَ فِيهِ الْوَدَكَ. فَقَالَ ابْنُ عَبَّاسٍ: قَدْ سَأَلْنَا رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَنْ ذَلِكَ فَقَالَ: "دِبَاغُهُ طُهُورُهُ". (م)', 'യസീദുബ്നു അബീ ഹബീബ്(റ): അബുൽഖൈർ അദ്ദേഹത്തോട് പറഞ്ഞു: ഇബ്നുവഅ്ലതുസ്സബഈ(റ) ഒരു തോൽ വസ്ത്രമണിഞ്ഞത് ഞാൻ കണ്ടു. ഞാനത് തൊട്ടുനോക്കി. അപ്പോൾ എന്നോടദ്ദേഹം പറഞ്ഞു: എന്തേ നീയിതു തൊടുന്നു? ഞാൻ ഇബ്നുഅബ്ബാസിനോട് ചോദിച്ചു: ഞങ്ങൾ പടിഞ്ഞാറ് ഭാഗത്തായിരിക്കും, ഞങ്ങളോടൊപ്പം ബർബേറിയക്കാരും മജൂസികളും ഉണ്ടാവും. അവർ ആടിനെ കൊണ്ടുവന്ന് അറുക്കും. ഞങ്ങളാരും അവർ അറുത്തത് തിന്നാറില്ല. ഞങ്ങളുടെയടുത്തേക്ക് നെയ്യ് നിറച്ച തോൽ പാത്രവുമായി വരും. ഇബ്നുഅബ്ബാസ്(റ) പറഞ്ഞു: ഞങ്ങളിക്കാര്യത്തെപ്പറ്റി ചോദിച്ചപ്പോൾ നബി(സ) പറഞ്ഞു: "ഊറക്കിട്ടാൽ അത് ശുദ്ധമാണ്."(മു)', 'يَزِيدَ بْنِ أَبِي حَبِيبٍ', 'യസീദുബ്നു അബീ ഹബീബ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 153, 153, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 50, 'عَنْ عَبْدِ اللهِ بْنِ الْمُغَفَّلِ رَضِيَ اللهُ عَنْهُ قَالَ: أَمَرَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِقَتْلِ الْكِلَابِ، ثُمَّ قَالَ: "مَا بَالُهُمْ وَبَالُ الْكِلَابِ" ثُمَّ رَخَّصَ فِي كَلْبِ الصَّيْدِ، وَكَلْبِ الْغَنَمِ وَقَالَ: "إِذَا وَلَغَ الْكَلْبُ فِي الْإِنَاءِ فَاغْسِلُوهُ سَبْعَ مَرَّاتٍ، وَعَفِّرُوهُ الثَّامِنَةَ فِي التُّرَابِ" وَفِي رِوَايَةِ يَحْيَى ابْنِ سَعِيدٍ: وَرَخَّصَ فِي كَلْبِ الْغَنَمِ، وَالصَّيْدِ وَالزَّرْعِ. (م)', 'അബ്ദുല്ലാഹിബ്നു മുഗഫ്ഫൽ(റ): നബി(സ) നായ്ക്കളെ കൊല്ലാൻ കൽപിച്ചുകൊണ്ട് പറഞ്ഞു: "അവരുടെയും നായ്ക്കളുടെയും അവസ്ഥ എന്താണ്?" പിന്നെ വേട്ടമൃഗത്തേയും ആടിനെയും അറുക്കുന്നതിൽ ഇളവു നൽകി. എന്നിട്ട് പറഞ്ഞു: "നായ പാത്രത്തിൽ തലയിട്ടാൽ അവരാ പാത്രം ഏഴു പ്രാവശ്യം കഴുകട്ടെ, എട്ടാം തവണ മണ്ണു പുരട്ടുകയും ചെയ്യട്ടെ." യഹ്യയിൽ നിന്നുള്ള ഒരു റിപ്പോർട്ടിൽ: ആടുവേട്ട, കൃഷി എന്നിവക്കുപയോഗിക്കുന്ന നായയുടെ കാര്യത്തിൽ ഇളവനുവദിച്ചു. (മു)', 'عَبْدِ اللهِ بْنِ الْمُغَفَّلِ', 'അബ്ദുല്ലാഹിബ്നു മുഗഫ്ഫൽ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 153, 153, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=1 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=10 and h.hadith_no=50), 1, 'وَفِي رِوَايَةٍ يَحْيَى ابْنِ سَعِيدٍ: وَرَخَّصَ فِي كَلْبِ الْغَنَمِ، وَالصَّيْدِ وَالزَّرْعِ. (م)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 51, 'عَنْ عَبْدِ اللهِ بْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: كَانَتِ الْكِلَابُ تُقْبِلُ وَتُدْبِرُ فِي الْمَسْجِدِ فِي زَمَانِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَلَمْ يَكُونُوا يَرُشُّونَ شَيْئًا مِنْ ذَلِكَ. (خ)', 'അബ്ദുല്ലാഹിബിൻ ഉമർ(റ): നബി(സ)യുടെ കാലത്ത് നായകൾ പള്ളിയിലൂടെ അങ്ങോട്ടുമിങ്ങോട്ടും കടന്നുപോവാറുണ്ടായിരുന്നു. എന്നാൽ അവിടെ അവർ(അനുചരന്മാർ) വെള്ളമൊഴിച്ച് വൃത്തിയാക്കാറുണ്ടായിരുന്നില്ല.⁷ (ബു)', 'عَبْدِ اللهِ بْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബിൻ ഉമർ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 153, 154, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=1 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 52, 'عَنْ أَبِي هُرَيْرَةَ وَأَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُمَا: دَخَلَ أَعْرَابِيٌّ الْمَسْجِدَ وَالنَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ جَالِسٌ، فَصَلَّى، فَلَمَّا فَرَغَ قَالَ: اللَّهُمَّ ارْحَمْنِي وَمُحَمَّدًا وَلَا تَرْحَمْ مَعَنَا أَحَدًا. فَالْتَفَتَ إِلَيْهِ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "لَقَدْ تَحَجَّرْتَ وَاسِعًا". فَلَمْ يَلْبَثْ أَنْ بَالَ فِي الْمَسْجِدِ، فَأَسْرَعَ إِلَيْهِ النَّاسُ، فَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَهْرِيقُوا عَلَيْهِ سَجْلًا مِنْ مَاءٍ، أَوْ: دَلْوًا مِنْ مَاءٍ". ثُمَّ قَالَ: "إِنَّمَا بُعِثْتُمْ مُيَسِّرِينَ وَلَمْ تُبْعَثُوا مُعَسِّرِينَ". حَسَنٌ صَحِيحٌ. (ق,د,ت,ن,جه)', 'അബൂഹുറൈറ(റ)വും അനസ്(റ)വും: നബി(സ) ഇരിക്കുമ്പോൾ ഒരു അഅ്റാബി പള്ളിയിൽ പ്രവേശിച്ച് നിസ്കരിച്ചു. നിസ്കാരശേഷം അയാൾ പ്രാർത്ഥിച്ചു: "അല്ലാഹുവേ, എനിക്കും മുഹമ്മദ്(സ)ക്കും നീ കരുണ ചെയ്യണേ. ഞങ്ങൾക്കൊപ്പം ആർക്കും കരുണ ചെയ്യല്ലേ." പ്രവാചകനപ്പോൾ അയാളിലേക്ക് തിരിഞ്ഞ് നോക്കി പറഞ്ഞു: "അല്ലാഹു വിശാലമാക്കിയതിനെ നീ ഇടുങ്ങിയതാക്കിയല്ലോ". അപ്പോഴേക്കും അയാൾ പള്ളിയിൽ മൂത്രമൊഴിച്ചിരുന്നു. അപ്പോൾ ജനങ്ങൾ അയാളുടെയടുത്ത് ഓടിക്കൂടി. പ്രവാചകർ പറഞ്ഞു: "അതിൽ ഒരു തൊട്ടി വെള്ളമൊഴിക്കുക, നിങ്ങൾ ബുദ്ധിമുട്ടിക്കപ്പെട്ടവരായിട്ടല്ല, എളുപ്പമാക്കപ്പെട്ടവരായാണ് നിയോഗിക്കപ്പെട്ടിട്ടുള്ളത്." (ബു,മു,ദ,തു,ന,ജ,)', 'أَبِي هُرَيْرَةَ وَأَنَسِ بْنِ مَالِكٍ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 154, 154, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=1 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 53, 'عَنْ عَبْدِ اللهِ بْنِ الْأَرْقَمِ رَضِيَ اللهُ عَنْهُ: قَالَ أُقِيمَتِ الصَّلَاةُ، فَأَخَذَ بِيَدِ رَجُلٍ فَقَدَّمَهُ، وَكَانَ إِمَامَ قَوْمِهِ، وَقَالَ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "إِذَا أُقِيمَتِ الصَّلَاةُ، وَوَجَدَ أَحَدُكُمُ الْخَلَاءَ، فَلْيَبْدَأْ بِالْخَلَاءِ". حَسَنٌ صَحِيحٌ. (د,ت)', 'അബ്ദുല്ലാഹിബ്നു അർഖം(റ): നിസ്കാരത്തിന് ഇഖാമത്ത് കൊടുക്കപ്പെട്ടു. ഒരാളെ പിടിച്ച് അദ്ദേഹം മുന്നിലേക്ക് ആക്കി. അയാൾ സമൂഹത്തിലെ നേതാവായിരുന്നു. ഈ സമയം അയാൾ പറഞ്ഞു: "ഇഖാമത്ത് കൊടുത്തശേഷം ആർക്കെങ്കിലും വിസർജ്ജിക്കാനാവശ്യമായാൽ ആദ്യം വിസർജ്ജിക്കട്ടെ" എന്ന് പ്രവാചകർ പറയുന്നത് ഞാൻ കേട്ടിട്ടുണ്ട്. (ഹദീസ് ഹസനും സഹീഹുമാണെന്ന് തുർമുദി പറയുന്നു). (ദ,തു)', 'عَبْدِ اللهِ بْنِ الْأَرْقَمِ', 'അബ്ദുല്ലാഹിബ്നു അർഖം(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 154, 154, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=1 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 54, 'عَنْ أُمِّ وَلَدٍ لِعَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ – رَضِيَ اللهُ عَنْهُ – قَالَتْ: قُلْتُ لِأُمِّ سَلَمَةَ رَضِيَ اللهُ عَنْهَا: إِنِّي امْرَأَةٌ أُطِيلُ ذَيْلِي وَأَمْشِي فِي الْمَكَانِ الْقَذِرِ؟ فَقَالَتْ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "يُطَهِّرُهُ مَا بَعْدَهُ". (د,ت,جه)', 'അബ്ദുർറഹ്മാനുബ്നു ഔഫിന്റെ ഒരു ഉമ്മു വലദ് (സ്വന്തം കുട്ടി ജനിച്ച അടിമ സ്ത്രീ): ഞാൻ ഉമ്മു സലമ(റ)യോട് ചോദിച്ചു: എന്റെ വസ്ത്രം നിലത്ത് ഏച്ചാണ് ഉണ്ടാവൽ. അഴുക്കിലൂടെ ഞാൻ നടക്കാറുമുണ്ട്. പ്രവാചകർ പറഞ്ഞു: "ശേഷം ഉള്ള ഭാഗം അത് വൃത്തിയാക്കും." (ദ,തു,ജ)', 'أُمِّ وَلَدٍ لِعَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ –', null, '⁷. അക്കാലത്ത് പള്ളിയിലും മറ്റും ഇന്നത്തെപ്പോലെ ഭദ്രമായ സംവിധാനം ഉണ്ടായിരുന്നില്ല.', null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 154, 154, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=1 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
